let revision=0,connected=false,pending=null,pushing=null,syncError=false;
function queueSave(){if(!connected||syncError)return;pending=JSON.parse(JSON.stringify(state));pushChanges()}
async function pushChanges(){if(pushing)return pushing;pushing=(async()=>{while(pending){const snapshot=pending;pending=null;$('#syncStatus').textContent='正在保存到本地…';try{const res=await fetch('/api/state',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({revision,state:snapshot})});const data=await res.json();if(!res.ok)throw Error(data.error);revision=data.revision;$('#syncStatus').textContent='已保存到本地 · 可供助手读取'}catch(e){syncError=true;$('#syncStatus').textContent='本地保存失败 · 浏览器副本仍保留';toast(e.message);break}}})().finally(()=>pushing=null);return pushing}
async function connect(){if(READ_ONLY_CATALOG){document.querySelector('#syncStatus').textContent='线上保存于当前浏览器，不与本地 Codex 同步';const note=document.querySelector('#editorSaveNote');if(note)note.textContent='线上角色与预选只保存在当前浏览器。要让 Codex / WorkBuddy 读取，请下载备份后导入本地工作台；线上版本不会写入你的电脑文件。';return}try{const res=await fetch('/api/state');if(!res.ok)throw Error();const data=await res.json();revision=data.revision;if(data.state){state=migrate(validate(data.state));styleFacetTextCache=new WeakMap();styleCountsCache=null;localStorage.setItem(KEY,JSON.stringify(state));render()}connected=true;queueSave()}catch(e){$('#syncStatus').textContent='未连接文件协作服务';toast('请双击项目根目录的启动衣境素材库.bat启动本地服务')}}
async function deleteActiveAsset(){if(READ_ONLY_CATALOG){toast('请在本地网站删除素材');return}if(!connected||syncError){toast('请先启动本地服务并完成同步');return}if(!active)return;const doomed=active;if(!await confirmAction(`确认从本机素材库删除“${doomed.title}”？预选和收藏会移除；未被其他素材引用的图片将移入本机回收站。`))return;await pushChanges();if(syncError)return;try{const res=await fetch('/api/assets/delete',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({assetId:doomed.id,revision})}),data=await res.json();if(!res.ok)throw Error(data.error||'删除失败');revision=data.revision;state=migrate(validate(data.state));localStorage.setItem(KEY,JSON.stringify(state));$('#detail').close();sessionStorage.setItem('yijing-asset-deletion-notice',`已删除“${data.title}”；${data.movedFiles} 个独立图片文件移入回收站，共用图片已保留。`);location.reload()}catch(e){toast('删除失败：'+e.message)}}
async function openAssetTrash(){if(!connected){toast('请先启动本地素材库服务');return}try{const res=await fetch('/api/assets/trash'),data=await res.json();if(!res.ok)throw Error(data.error||'读取失败');const rows=data.items||[];$('#assetTrashList').innerHTML=rows.length?rows.map(x=>`<article class="asset-trash-row"><div><strong>${esc(x.title||x.assetId)}</strong><p>${esc(x.assetId)} · ${esc(x.deletedAt||'删除时间未知')} · ${x.movedFiles||0} 个图片文件</p></div>${x.restored?'<span class="trash-restored">已恢复</span>':`<button type="button" data-restore-asset="${esc(x.batch)}">恢复素材</button>`}</article>`).join(''):'<p class="note">回收站为空。</p>';$('#assetTrashDialog').showModal()}catch(e){toast('打开回收站失败：'+e.message)}}
async function restoreAssetFromTrash(batch,button){if(!connected||syncError){toast('请先连接本地服务');return}await pushChanges();if(syncError)return;button.disabled=true;try{const res=await fetch('/api/assets/restore',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({batch,revision})}),data=await res.json();if(!res.ok)throw Error(data.error||'恢复失败');revision=data.revision;state=migrate(validate(data.state));localStorage.setItem(KEY,JSON.stringify(state));$('#assetTrashDialog').close();sessionStorage.setItem('yijing-asset-deletion-notice',`已恢复“${data.title}”及其回收图片。`);location.reload()}catch(e){button.disabled=false;toast('恢复失败：'+e.message)}}
