function requestAction(message,initial,confirmOnly){return new Promise(resolve=>{const dialog=$('#actionDialog'),input=$('#actionValue');$('#actionMessage').textContent=message;input.hidden=confirmOnly;input.value=initial||'';let done=false;const finish=value=>{if(done)return;done=true;dialog.close();resolve(value)};$('#actionForm').onsubmit=e=>{e.preventDefault();if(!confirmOnly&&!input.value.trim()){input.focus();return}finish(confirmOnly?true:input.value.trim())};$('#actionCancel').onclick=()=>finish(confirmOnly?false:null);dialog.oncancel=e=>{e.preventDefault();finish(confirmOnly?false:null)};dialog.showModal();if(!confirmOnly)input.focus()})}
function askName(message,initial=''){return requestAction(message,initial,false)}
function confirmAction(message){return requestAction(message,'',true)}

async function addRoleToProject(projectId){const dest=state.projects.find(p=>p.id===projectId);if(!dest)return;const name=await askName('在“'+dest.name+'”添加角色');if(!name)return;const r={id:'r-'+crypto.randomUUID(),name,picks:{},projectId,requirements:'',design:'',status:'设计中'};state.roles.push(r);state.currentProject=projectId;state.current=r.id;collapsedProjects[projectId]=false;rememberFolds();save();toast('已添加角色：'+name)}
function rememberFolds(){try{localStorage.setItem('yijing-project-folds',JSON.stringify(collapsedProjects))}catch(e){}}
async function deleteRoleById(id){const r=state.roles.find(r=>r.id===id);if(!r)return;if(!await confirmAction('删除角色“'+r.name+'”及其预选？这不会删除同项目其他角色。本地服务保留历史版本。'))return;state.roles=state.roles.filter(x=>x.id!==id);if(state.current===id)state.current=state.roles.find(x=>x.projectId===state.currentProject)?.id||'';save();if($('#roleEditor').open)$('#roleEditor').close();toast('已删除角色：'+r.name)}
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.toggle){const id=b.dataset.toggle;collapsedProjects[id]=!collapsedProjects[id];rememberFolds();render()}if(b.dataset.addrole)await addRoleToProject(b.dataset.addrole);if(b.dataset.roleedit){const r=state.roles.find(r=>r.id===b.dataset.roleedit);if(r){state.current=r.id;state.currentProject=r.projectId;save();openRoleEditor()}}if(b.dataset.roledelete)await deleteRoleById(b.dataset.roledelete)});

function icon(name){const paths={plus:'<path d="M12 5v14M5 12h14"/>',more:'<circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/>',down:'<path d="m8 10 4 4 4-4"/>',right:'<path d="m10 8 4 4-4 4"/>',arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',heart:'<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z"/>',grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',board:'<rect x="4" y="4" width="16" height="16" rx="2"/><path d="M9 4v16M9 10h11"/>'};return `<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.more}</svg>`}
var contextTrigger;
function closeContextMenu(restoreFocus=false){const menu=$('#contextMenu');if(menu)menu.hidden=true;if(restoreFocus&&contextTrigger?.isConnected)contextTrigger.focus()}
function showContextMenu(button,type,id){contextTrigger=button;const menu=$('#contextMenu');let actions=[];if(type==='project'){const index=state.projects.findIndex(p=>p.id===id);actions=[['addrole','添加角色',false],['projectrename','重命名项目',false],['up','上移项目',index<=1],['down','下移项目',index===state.projects.length-1],['projectdelete','删除项目',false]]}else{actions=[['roleedit','编辑角色方案',false],['roledelete','删除角色',false]]}menu.innerHTML=actions.map(([key,label,disabled])=>`<button role="menuitem" data-${key}="${esc(id)}" ${disabled?'disabled':''} class="${key.includes('delete')?'danger':''}">${label}</button>`).join('');menu.hidden=false;const rect=button.getBoundingClientRect();menu.style.left=Math.max(8,Math.min(rect.right+6,window.innerWidth-190))+'px';menu.style.top=Math.max(8,Math.min(rect.top,window.innerHeight-menu.offsetHeight-8))+'px';menu.querySelector('button:not(:disabled)')?.focus()}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(b?.dataset.projectmenu){showContextMenu(b,'project',b.dataset.projectmenu);return}if(b?.dataset.rolemenu){showContextMenu(b,'role',b.dataset.rolemenu);return}closeContextMenu()});
document.addEventListener('keydown',e=>{const menu=$('#contextMenu');if(menu.hidden)return;if(e.key==='Escape'){closeContextMenu(true)}if(['ArrowDown','ArrowUp'].includes(e.key)){e.preventDefault();const buttons=[...menu.querySelectorAll('button:not(:disabled)')],index=buttons.indexOf(document.activeElement);buttons[(index+(e.key==='ArrowDown'?1:-1)+buttons.length)%buttons.length]?.focus()}});
document.querySelectorAll('.nav').forEach(b=>{const type=b.dataset.tab,caption={all:'全部素材',saved:'我的收藏',board:'角色预选'}[type],counter={all:'allCount',saved:'favCount',board:'boardCount'}[type];b.innerHTML=icon({all:'grid',saved:'heart',board:'board'}[type])+`<span class="nav-label">${caption}</span><span id="${counter}" class="nav-count"></span>`});
